CREATE TABLE parking_slots (id INTEGER PRIMARY KEY AUTOINCREMENT, slot_number TEXT UNIQUE NOT NULL, status TEXT NOT NULL);
CREATE TABLE parking_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, registration TEXT NOT NULL, slot_id INTEGER NOT NULL, entry_time TEXT NOT NULL, exit_time TEXT, duration_minutes INTEGER, fee INTEGER, status TEXT NOT NULL);
CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER UNIQUE NOT NULL, amount INTEGER NOT NULL, paid_at TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE waiting_queue (id INTEGER PRIMARY KEY AUTOINCREMENT, registration TEXT UNIQUE NOT NULL, requested_at TEXT NOT NULL);
